Object.assign(View, {
  renderTetrisIconAnimation(canvas) {
    const ctx = canvas.getContext("2d");
    let step = 0;
    const interval = setInterval(() => {
      if (!document.body.contains(canvas)) {
        clearInterval(interval);
        return;
      }
      step++;
      const style = getComputedStyle(document.body);
      const ink = style.getPropertyValue('--ink').trim() || '#090b0a';
      const cyan = style.getPropertyValue('--cyan').trim() || '#91f3a8';
      const green = style.getPropertyValue('--green').trim() || '#20ef4f';

      ctx.fillStyle = ink;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      const sz = 8;
      const blocks = [
        {x: 2, y: 1 + (step % 3), color: cyan},
        {x: 3, y: 1 + (step % 3), color: cyan},
        {x: 2, y: 2 + (step % 3), color: green},
        {x: 3, y: 2 + (step % 3), color: green}
      ];

      blocks.forEach(b => {
        ctx.fillStyle = b.color;
