            <button class="pong-touch-btn" data-action="down">▼ DOWN</button>
          </div>
        </div>
      `;
      document.body.appendChild(overlay);

      overlay.querySelector(".pong-close-btn").addEventListener("click", () => {
        this.closePongModal();
      });
      overlay.addEventListener("click", (e) => {
        if (e.target === overlay) this.closePongModal();
      });

      overlay.querySelectorAll(".pong-diff-btn").forEach(btn => {
        btn.addEventListener("click", () => {
          overlay.querySelectorAll(".pong-diff-btn").forEach(b => b.classList.remove("is-active"));
          btn.classList.add("is-active");
          const diff = btn.getAttribute("data-diff");
          if (this.pongSetDifficulty) this.pongSetDifficulty(diff);
        });
      });

      this.initPongEngine(overlay);
    }
    overlay.classList.add("is-active");
    if (this.pongReset) this.pongReset();
  },

  closePongModal() {
    const overlay = document.querySelector(".pong-modal-overlay");
    if (overlay) overlay.classList.remove("is-active");
    if (this.pongPause) this.pongPause();
  },

  initPongEngine(overlay) {
    const canvas = overlay.querySelector("#pong-game-canvas");
    const ctx = canvas.getContext("2d");
    const playerScoreEl = overlay.querySelector("#pong-player-score");
    const aiScoreEl = overlay.querySelector("#pong-ai-score");

    const WIDTH = canvas.width;
    const HEIGHT = canvas.height;

    let playerScore = 0;
    let aiScore = 0;
    let difficulty = "medium"; // easy, medium, hard, impossible

    const paddleWidth = 10;
    const paddleHeight = 60;
    const ballSize = 8;

    let player = {
      x: 15,
      y: HEIGHT / 2 - paddleHeight / 2,
      width: paddleWidth,
      height: paddleHeight,
      score: 0,
      dy: 0
    };

    let ai = {
      x: WIDTH - 25,
      y: HEIGHT / 2 - paddleHeight / 2,
      width: paddleWidth,
      height: paddleHeight,
      score: 0
    };

    let ball = {
      x: WIDTH / 2,
      y: HEIGHT / 2,
      vx: 4,
      vy: 3,
      speed: 5
    };

    let isPaused = false;
    let gameOver = false;

    this.pongSetDifficulty = (diff) => {
      difficulty = diff;
      this.pongReset();
    };

    this.pongReset = () => {
      playerScore = 0;
      aiScore = 0;
      playerScoreEl.textContent = `PLAYER: ${playerScore}`;
      aiScoreEl.textContent = `AI: ${aiScore}`;
      resetBall();
      isPaused = false;
      gameOver = false;
    };

    this.pongPause = () => {
      isPaused = true;
    };

    function resetBall(servingToPlayer = true) {
      ball.x = WIDTH / 2;
      ball.y = HEIGHT / 2;
      ball.speed = 5;
      const angle = (Math.random() * 0.6 - 0.3) * Math.PI;
      const dir = servingToPlayer ? -1 : 1;
      ball.vx = dir * ball.speed * Math.cos(angle);
      ball.vy = ball.speed * Math.sin(angle);
    }

    function update() {
      if (!overlay.classList.contains("is-active") || isPaused || gameOver) return;

      // Move player paddle
      player.y += player.dy;
      if (player.y < 0) player.y = 0;
      if (player.y > HEIGHT - player.height) player.y = HEIGHT - player.height;

      // AI Logic based on difficulty
      let aiSpeed = 3.2;
      let errorMargin = 25;

      if (difficulty === "easy") {
        aiSpeed = 2.5;
        errorMargin = 45;
      } else if (difficulty === "medium") {
        aiSpeed = 4.0;
        errorMargin = 20;
      } else if (difficulty === "hard") {
        aiSpeed = 5.8;
        errorMargin = 8;
      } else if (difficulty === "impossible") {
        aiSpeed = 8.5;
        errorMargin = 0;
      }

      let aiTarget = ball.y - ai.height / 2;
      if (Math.abs(ai.y - aiTarget) > 3) {
        if (ai.y < aiTarget + (Math.random() - 0.5) * errorMargin) {
          ai.y += aiSpeed;
        } else if (ai.y > aiTarget + (Math.random() - 0.5) * errorMargin) {
          ai.y -= aiSpeed;
        }
      }
      if (ai.y < 0) ai.y = 0;
      if (ai.y > HEIGHT - ai.height) ai.y = HEIGHT - ai.height;

      // Move ball
      ball.x += ball.vx;
      ball.y += ball.vy;

      // Wall bounce (top/bottom)
      if (ball.y <= 0) {
        ball.y = 0;
        ball.vy *= -1;
      } else if (ball.y >= HEIGHT - ballSize) {
        ball.y = HEIGHT - ballSize;
        ball.vy *= -1;
      }

      // Player collision
      if (
        ball.x <= player.x + player.width &&
        ball.x + ballSize >= player.x &&
        ball.y + ballSize >= player.y &&
        ball.y <= player.y + player.height
      ) {
        let hitPoint = (ball.y + ballSize / 2) - (player.y + player.height / 2);
        let normalizedHit = hitPoint / (player.height / 2);
        let bounceAngle = normalizedHit * (Math.PI / 4);
        ball.speed = Math.min(ball.speed + 0.3, 11);
        ball.vx = ball.speed * Math.cos(bounceAngle);
        ball.vy = ball.speed * Math.sin(bounceAngle);
        ball.x = player.x + player.width;
      }

      // AI collision
      if (
        ball.x + ballSize >= ai.x &&
        ball.x <= ai.x + ai.width &&
        ball.y + ballSize >= ai.y &&
        ball.y <= ai.y + ai.height
      ) {
        let hitPoint = (ball.y + ballSize / 2) - (ai.y + ai.height / 2);
        let normalizedHit = hitPoint / (ai.height / 2);
        let bounceAngle = normalizedHit * (Math.PI / 4);
        ball.speed = Math.min(ball.speed + 0.3, 11);
        ball.vx = -ball.speed * Math.cos(bounceAngle);
        ball.vy = ball.speed * Math.sin(bounceAngle);
        ball.x = ai.x - ballSize;
      }

      // Scoring
      if (ball.x < 0) {
        aiScore++;
        aiScoreEl.textContent = `AI: ${aiScore}`;
        if (aiScore >= 5) {
          gameOver = true;
        } else {
          resetBall(true);
        }
      } else if (ball.x > WIDTH) {
        playerScore++;
        playerScoreEl.textContent = `PLAYER: ${playerScore}`;
        if (playerScore >= 5) {
          gameOver = true;
        } else {
          resetBall(false);
        }
      }
    }

    function draw() {
      ctx.fillStyle = '#090b0a';
      ctx.fillRect(0, 0, WIDTH, HEIGHT);

      // Center net
      ctx.strokeStyle = '#1b221d';
      ctx.lineWidth = 2;
      ctx.setLineDash([6, 6]);
      ctx.beginPath();
      ctx.moveTo(WIDTH / 2, 0);
      ctx.lineTo(WIDTH / 2, HEIGHT);
      ctx.stroke();
      ctx.setLineDash([]);

      // Player Paddle (Cyan)
      ctx.fillStyle = '#91f3a8';
      ctx.shadowColor = '#91f3a8';
      ctx.shadowBlur = 8;
      ctx.fillRect(player.x, player.y, player.width, player.height);

      // AI Paddle (Green)
      ctx.fillStyle = '#20ef4f';
      ctx.shadowColor = '#20ef4f';
      ctx.fillRect(ai.x, ai.y, ai.width, ai.height);

      // Ball (Red)
      ctx.fillStyle = '#ff2244';
      ctx.shadowColor = '#ff2244';
      ctx.fillRect(ball.x, ball.y, ballSize, ballSize);
      ctx.shadowBlur = 0;

      if (gameOver) {
        ctx.fillStyle = "rgba(9, 11, 10, 0.85)";
        ctx.fillRect(0, 0, WIDTH, HEIGHT);
        ctx.fillStyle = playerScore >= 5 ? "#20ef4f" : "#ff2244";
        ctx.font = "bold 18px monospace";
        ctx.textAlign = "center";
        ctx.fillText(playerScore >= 5 ? "VICTORY // YOU WIN" : "DEFEAT // AI WINS", WIDTH / 2, HEIGHT / 2 - 10);
        ctx.fillStyle = "#91f3a8";
        ctx.font = "12px monospace";
        ctx.fillText("PRESS ENTER TO RESTART", WIDTH / 2, HEIGHT / 2 + 20);
      } else if (isPaused) {
        ctx.fillStyle = "rgba(9, 11, 10, 0.75)";
        ctx.fillRect(0, 0, WIDTH, HEIGHT);
        ctx.fillStyle = "#91f3a8";
        ctx.font = "bold 16px monospace";
        ctx.textAlign = "center";
        ctx.fillText("PAUSED", WIDTH / 2, HEIGHT / 2);
      }
    }

    function loop() {
      update();
      draw();
      requestAnimationFrame(loop);
    }

    const handleKeyDown = (e) => {
      if (!overlay.classList.contains("is-active")) return;
      if (e.key === "ArrowUp" || e.key === "w" || e.key === "W") {
        player.dy = -6;
        e.preventDefault();
      } else if (e.key === "ArrowDown" || e.key === "s" || e.key === "S") {
        player.dy = 6;
        e.preventDefault();
      } else if (e.key === " ") {
        isPaused = !isPaused;
        e.preventDefault();
      } else if (e.key === "Enter" && gameOver) {
        this.pongReset();
        e.preventDefault();
      }
    };

    const handleKeyUp = (e) => {
      if (
        (e.key === "ArrowUp" || e.key === "w" || e.key === "W" ||
         e.key === "ArrowDown" || e.key === "s" || e.key === "S")
      ) {
        player.dy = 0;
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    window.addEventListener("keyup", handleKeyUp);

    overlay.querySelectorAll(".pong-touch-btn").forEach(btn => {
      const act = btn.getAttribute("data-action");
      btn.addEventListener("mousedown", () => { player.dy = act === "up" ? -6 : 6; });
      btn.addEventListener("mouseup", () => { player.dy = 0; });
      btn.addEventListener("touchstart", (e) => { e.preventDefault(); player.dy = act === "up" ? -6 : 6; });
      btn.addEventListener("touchend", () => { player.dy = 0; });
    });

    this.pongReset();
    requestAnimationFrame(loop);
  }
});

// Hook into View.renderJuegos to add Pong Card
const prevRenderJuegosPong = View.renderJuegos;
View.renderJuegos = function(games) {
  if (prevRenderJuegosPong) prevRenderJuegosPong.call(this, games);
  const container = document.getElementById("juegos-body");
  if (!container) return;

  games.forEach((item, index) => {
    if (item.id === "pong") {
      const iconCard = document.createElement("div");
      iconCard.className = "pong-app-icon-card";
      iconCard.style.setProperty("--entry-index", index);

      const iconBox = document.createElement("div");
      iconBox.className = "pong-app-icon";
      const canvas = document.createElement("canvas");
      canvas.className = "pong-icon-canvas";
      canvas.width = 56;
      canvas.height = 56;
      iconBox.appendChild(canvas);

      const label = document.createElement("h4");
      label.className = "pong-icon-label";
      label.textContent = this.localized(item, "title");

      iconCard.append(iconBox, label);
      iconCard.addEventListener("click", () => {
        Controller.openPongModal();
      });

      this.renderPongIconAnimation(canvas);
      container.appendChild(iconCard);
    }
  });
};

Object.assign(Controller, {
  openPongModal() {
    View.openPongModal();
  }
});
"}

