  renderPongIconAnimation(canvas) {
    const ctx = canvas.getContext("2d");
    let frame = 0;
    const interval = setInterval(() => {
      if (!document.body.contains(canvas)) {
        clearInterval(interval);
        return;
      }
      frame++;
      const style = getComputedStyle(document.body);
      const ink = style.getPropertyValue('--ink').trim() || '#090b0a';
      const cyan = style.getPropertyValue('--cyan').trim() || '#91f3a8';
      const green = style.getPropertyValue('--green').trim() || '#20ef4f';

      ctx.fillStyle = ink;
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      // Paddle 1
      ctx.fillStyle = cyan;
      ctx.fillRect(6, 18 + Math.sin(frame * 0.2) * 10, 4, 18);
      // Paddle 2
      ctx.fillStyle = green;
      ctx.fillRect(46, 18 - Math.sin(frame * 0.2) * 10, 4, 18);
      // Ball
      ctx.fillStyle = '#ff2244';
      const bx = 15 + ((frame * 3) % 26);
      const by = 28 + Math.sin(frame * 0.3) * 12;
      ctx.fillRect(bx, by, 4, 4);
    }, 120);
